// Custom worker entry: routes /ws/* to the PokerRoom Durable Object,
// everything else to the SvelteKit worker generated by adapter-cloudflare.
// "sveltekit-worker" is aliased in wrangler.jsonc to .svelte-kit/cloudflare/_worker.js.
import svelteWorker from 'sveltekit-worker';
export { PokerRoom } from './lib/server/poker-room';

const WS_PATH = /^\/ws\/([A-Za-z0-9_-]{4,32})$/;

export default {
	async fetch(request, env, ctx) {
		const match = WS_PATH.exec(new URL(request.url).pathname);
		if (match) {
			if (request.headers.get('Upgrade')?.toLowerCase() !== 'websocket') {
				return new Response('Expected WebSocket', { status: 426 });
			}
			return env.POKER_ROOM.get(env.POKER_ROOM.idFromName(match[1])).fetch(request);
		}
		return svelteWorker.fetch(request, env, ctx);
	}
} satisfies ExportedHandler<Env>;
